const {test}=require('node:test');
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const vm=require('node:vm');
const {webcrypto}=require('node:crypto');
const WB=require('../wellbeing-core.js');
const root=path.join(__dirname,'..');
test('all meditation modes finish exactly at duration and never prescribe a breath hold',()=>{for(const [kind,s]of Object.entries(WB.sessions)){assert.ok(s.steps.length);assert.ok(!s.pattern||s.pattern.length===2);for(let elapsed=0;elapsed<=1201;elapsed++){const frame=WB.frame(kind,elapsed,1200);assert.equal(frame.done,elapsed>=1200);assert.ok(frame.remaining>=0&&frame.remaining<=1200);assert.ok(['inhale','exhale','natural'].includes(frame.phase));}assert.equal(WB.frame(kind,5,60,true).phase,'natural');}assert.equal(WB.frame('settle',3.9,60).phase,'inhale');assert.equal(WB.frame('settle',4,60).phase,'exhale');assert.equal(WB.frame('settle',10,60).phase,'inhale');});
test('grounding, body awareness and silent timers allow natural breathing throughout',()=>{for(const kind of ['ground','body','quiet'])for(let i=0;i<300;i++)assert.equal(WB.frame(kind,i,300).phase,'natural');assert.equal(WB.clock(65),'1:05');assert.equal(WB.clock(0),'0:00');});
test('daily prompts vary across the week and journeys contain seven distinct practical steps',()=>{const prompts=new Set();for(let i=1;i<=7;i++)prompts.add(WB.journalPrompt(`2026-10-${String(i).padStart(2,'0')}`,'morning'));assert.equal(prompts.size,7);assert.notEqual(WB.journalPrompt('2026-10-20','morning'),WB.journalPrompt('2026-10-20','evening'));for(const steps of Object.values(WB.journeys))assert.equal(new Set(steps).size,7);for(const lang of ['en','es','fr'])assert.equal(WB.affirmations[lang].length,5);});
test('sync record merge preserves concurrent additions and latest deletion tombstones',()=>{const a={id:'a',updated:2,payload:{note:'local'}};const b={id:'b',updated:1};const deleted={id:'c',updated:5,deleted:true};const merged=WB.mergeRecords([a,deleted],[{id:'a',updated:1},b,{id:'c',updated:3}]);assert.equal(merged.length,3);assert.equal(merged.find(r=>r.id==='a').payload.note,'local');assert.equal(merged.find(r=>r.id==='c').deleted,true);});
function harness(){
 const nodes=new Map(),records=new Map();let clock=0;const timers=new Map();let timerID=0;
 const node=()=>({parentElement:{after(){}},value:'',textContent:'',dataset:{},style:{setProperty(k,v){this[k]=v;}},children:[],handlers:{},attrs:{},hidden:false,disabled:false,files:[],classList:{toggle(){},add(){},remove(){}},setAttribute(k,v){this.attrs[k]=v;},removeAttribute(k){delete this.attrs[k];},append(...x){this.children.push(...x);},prepend(...x){this.children.unshift(...x);},after(){},before(){},replaceChildren(...x){this.children=x;},addEventListener(e,fn){this.handlers[e]=fn;},querySelectorAll(){return [];},showModal(){this.open=true;},close(){this.open=false;this.handlers.close?.();},focus(){},scrollIntoView(){},remove(){},pause(){},reset(){},select(){},setCustomValidity(){},reportValidity(){}});
 const get=id=>{if(!nodes.has(id))nodes.set(id,node());return nodes.get(id);};
 const filters=['All','Confidence','Focus','Resilience','Growth','Calm'].map(category=>Object.assign(node(),{dataset:{category}}));
 const db={createObjectStore(){},transaction(){const tx={aborted:false,abort(){this.aborted=true;this.onabort?.();}};tx.objectStore=()=>({getAll(){const r={};queueMicrotask(()=>{r.result=structuredClone([...records.values()]);r.onsuccess?.();});return r;},put(r){records.set(r.id,structuredClone(r));},delete(id){records.delete(id);}});queueMicrotask(()=>queueMicrotask(()=>{if(!tx.aborted)tx.oncomplete?.();}));return tx;}};
 const indexedDB={open(){const r={result:db};queueMicrotask(()=>r.onsuccess());return r;}};
 const storage=new Map();const context=vm.createContext({localStorage:{getItem:key=>storage.get(key)||null,setItem:(key,value)=>storage.set(key,value)},Date,Math,console,crypto:webcrypto,TextEncoder,TextDecoder,Blob,URL,AbortController,AbortSignal,Uint8Array,structuredClone,performance:{now:()=>clock},btoa:s=>Buffer.from(s,'binary').toString('base64'),atob:s=>Buffer.from(s,'base64').toString('binary'),indexedDB,document:{hidden:false,documentElement:{dataset:{}},body:node(),querySelector:()=>node(),querySelectorAll:()=>filters,createElement:node,createTextNode:text=>({textContent:text}),getElementById:get,handlers:{},addEventListener(e,fn){(this.handlers[e]??=[]).push(fn);}},window:{addEventListener(){}},location:{protocol:'file:',href:'https://example.com'},navigator:{onLine:true},matchMedia:()=>({matches:false}),setTimeout:()=>0,clearTimeout(){},setInterval:fn=>{timers.set(++timerID,fn);return timerID;},clearInterval:id=>timers.delete(id),fetch:async()=>{throw Error('No network in this test');}});
 for(const name of ['quotes.js','daily-quotes.js','scenes.js','app.js','enhancements.js','companion.js','wellbeing-core.js','wellbeing.js','growth-core.js','growth.js'])vm.runInContext(fs.readFileSync(path.join(root,name),'utf8'),context,{filename:name});
 return {context,get,records,storage,run:s=>vm.runInContext(s,context),advance:ms=>clock+=ms,ready:async()=>{for(let i=0;i<10;i++)await Promise.resolve();}};
}
test('timer pause and resume preserve elapsed time, stop resets controls and completion records once',async()=>{const h=harness();await h.ready();h.get('session-kind').value='settle';h.get('session-minutes').value='1';h.get('session-sound').value='off';await h.get('session-start').onclick();h.advance(12000);h.run('renderSession()');assert.equal(h.get('session-clock').textContent,'0:48');h.run('pauseSession()');h.advance(20000);h.run('renderSession()');assert.equal(h.get('session-clock').textContent,'0:48');await h.get('session-pause').onclick();h.advance(48000);h.run('renderSession()');assert.equal(h.get('session-clock').textContent,'0:00');assert.equal(h.run('studioPrefs.sessions.length'),1);h.run('renderSession()');assert.equal(h.run('studioPrefs.sessions.length'),1);assert.equal(h.get('session-start').disabled,false);});
test('vault encrypts existing journal entries, clears plaintext only after storage and rejects wrong passwords',async()=>{const h=harness();await h.ready();h.run("state.companion.journal[dayKey()]={mood:'low',note:'A private earlier reflection'}");await h.run("saveJournal({day:dayKey(),note:'A private new entry'})");h.get('vault-password').value='testing-passphrase-2026';await h.get('vault-enable').onclick();assert.equal(h.run('!!studioPrefs.vault'),true);assert.equal(h.run('state.companion.journal[dayKey()].note'),'');const stored=JSON.stringify([...h.records.values()]);assert.ok(!stored.includes('A private'));h.run('lockJournal()');h.get('vault-password').value='wrong-passphrase-2026';await h.get('vault-open').onclick();assert.equal(h.run('vaultKey'),null);assert.match(h.get('vault-status').textContent,/incorrect/);h.get('vault-password').value='testing-passphrase-2026';await h.get('vault-open').onclick();assert.equal(h.run('!!vaultKey'),true);assert.ok(h.get('journal-list').children.length>=2);h.run('lockJournal()');assert.equal(h.get('journal-list').children.length,0);});
test('locked journal refuses writes and full backups retain encrypted records without private words',async()=>{const h=harness();await h.ready();h.get('vault-password').value='testing-passphrase-2026';await h.get('vault-enable').onclick();await h.run("saveJournal({day:dayKey(),note:'Secret sunflower note'})");h.run('lockJournal()');await assert.rejects(h.run("saveJournal({note:'another note'})"),/Unlock/);const backup=await h.run('fullStudioBackup()');assert.ok(!JSON.stringify(backup).includes('Secret sunflower'));assert.equal(backup.records.filter(r=>r.encrypted).length,1);assert.ok(backup.quoteBackup.data.studio.vault);});
test('studio backup validation rejects executable media and preserves newer local records on merge',async()=>{const h=harness();await h.ready();assert.throws(()=>h.run("validateStudioRows([{id:'evil',kind:'vision',updated:1,payload:{image:'javascript:alert(1)'}}])"),/Invalid photo/);assert.throws(()=>h.run("validateStudioRows([{id:'x',kind:'journal',updated:1,payload:{note:3}}])"),/Invalid journal/);h.run("studioPrefs.journeys.Confidence=[0,1];persist()");const backup=await h.run('fullStudioBackup()');backup.records=[{id:'image',kind:'vision',updated:10,payload:{title:'A goal',image:'data:image/jpeg;base64,YQ=='}}];h.context.testBackup=backup;await h.run('importStudioBackup(testBackup)');assert.equal(h.records.get('image').payload.title,'A goal');assert.equal(h.run('studioPrefs.journeys.Confidence.length'),2);});
test('calendar event has daily recurrence and an explicit alert; sync rejects unsafe URL before requests',async()=>{const h=harness();await h.ready();const ics=h.run("calendarFile('09:30')");assert.match(ics,/RRULE:FREQ=DAILY/);assert.match(ics,/BEGIN:VALARM/);assert.match(ics,/T093000/);h.get('sync-url').value='http://example.com/secret';h.get('sync-connect').onclick();assert.match(h.get('sync-status').textContent,/HTTPS/);assert.equal(h.run('syncSecrets'),null);});
test('encrypted sync creates conditionally, never sends plaintext and preserves data on a concurrent-write conflict',async()=>{const h=harness();await h.ready();const calls=[];h.context.fetch=async(url,opts)=>{calls.push({url,opts});return opts.method==='PUT'?{ok:true,status:201}:{ok:false,status:404};};h.run("syncSecrets={url:'https://sync.example/motive.json',phrase:'a-shared-test-phrase',user:'',password:''};state.name='Private test name'");await h.run('syncStudio()');assert.equal(calls.length,2);const put=calls[1].opts;assert.equal(put.headers['If-None-Match'],'*');assert.ok(!put.body.includes('Private test name'));assert.equal(JSON.parse(put.body).app,'motive-encrypted-sync');const remote=JSON.parse(put.body);calls.length=0;h.context.fetch=async(url,opts)=>{calls.push(opts);return opts.method==='PUT'?{ok:false,status:412}:{ok:true,headers:{get:()=> '"etag-1"'},json:async()=>remote};};await h.run('syncStudio()');assert.equal(calls[1].headers['If-Match'],'"etag-1"');assert.match(h.get('sync-status').textContent,/Another device/);assert.equal(h.run('state.name'),'Private test name');assert.equal(h.run('syncBusy'),false);});
test('ordinary legacy backup cannot reintroduce plaintext notes into a locked journal',async()=>{const h=harness();await h.ready();h.get('vault-password').value='testing-passphrase-2026';await h.get('vault-enable').onclick();const backup=JSON.parse(JSON.stringify(h.run('backupData()')));backup.data.companion.journal={'2026-10-20':{note:'unencrypted private note'}};h.context.legacyBackup=backup;assert.throws(()=>h.run('mergeBackup(legacyBackup)'),/unlocked reflections/);assert.ok(!h.run('JSON.stringify(state)').includes('unencrypted private note'));});
test('locking during an asynchronous unlock cannot reveal journal contents after returning',async()=>{const h=harness();await h.ready();h.get('vault-password').value='testing-passphrase-2026';await h.get('vault-enable').onclick();await h.run("saveJournal({note:'A private thought'})");h.run('lockJournal()');h.get('vault-password').value='testing-passphrase-2026';const opening=h.get('vault-open').onclick();h.run('lockJournal()');await opening;assert.equal(h.run('vaultKey'),null);assert.equal(h.get('journal-list').children.length,0);});
test('failed encrypted-storage transaction leaves earlier plaintext reflection intact',async()=>{const h=harness();await h.ready();h.run("state.companion.journal[dayKey()]={note:'Keep this safe'};dbWrite=async()=>{throw Error('Storage is full')}");h.get('vault-password').value='testing-passphrase-2026';await h.get('vault-enable').onclick();assert.equal(h.run('state.companion.journal[dayKey()].note'),'Keep this safe');assert.equal(h.run('!!studioPrefs.vault'),false);assert.match(h.get('vault-status').textContent,/Storage is full/);});
test('sync refuses an unversioned server response instead of overwriting remote data',async()=>{const h=harness();await h.ready();let calls=0;h.context.fetch=async()=>{calls++;return {ok:true,headers:{get:()=>null}};};h.run("syncSecrets={url:'https://sync.example/motive.json',phrase:'shared-phrase-long',user:'',password:''}");await h.run('syncStudio()');assert.equal(calls,1);assert.match(h.get('sync-status').textContent,/ETag/);});
test('voice recording requests only audio, saves locally and releases microphone tracks',async()=>{const h=harness();await h.ready();let released=false,requested=false;h.context.navigator.mediaDevices={getUserMedia:async options=>{assert.equal(options.audio,true);assert.equal(options.video,undefined);requested=true;return {getTracks:()=>[{stop(){released=true;}}]};}};class Recorder{constructor(){this.mimeType='audio/webm';this.state='inactive';}start(){this.state='recording';}async stop(){this.state='inactive';this.ondataavailable({data:new Blob(['test audio'],{type:'audio/webm'})});await this.onstop();}}h.context.MediaRecorder=Recorder;h.context.window.MediaRecorder=Recorder;h.run("fileData=async()=> 'data:audio/webm;base64,YQ=='");h.get('recording-title').value='A reminder';await h.run("startRecording('voice')");assert.equal(requested,true);assert.equal(released,false);await h.run('recording.stop()');assert.equal(released,true);assert.equal([...h.records.values()].find(r=>r.kind==='voice').payload.title,'A reminder');assert.equal(h.run('recording'),null);});
function installSpeech(h){let voices=[{voiceURI:'voice-us',name:'US Reader',lang:'en-US',default:true,localService:true},{voiceURI:'voice-uk',name:'UK Reader',lang:'en-GB',localService:true},{voiceURI:'voice-es',name:'Spanish Reader',lang:'es-ES',localService:false}];const spoken=[];const events={};class Utterance{constructor(text){this.text=text;}}const engine={getVoices:()=>voices,speak:u=>spoken.push(u),cancel:()=>{spoken.at(-1)?.onerror?.({error:'canceled'});},addEventListener:(name,fn)=>events[name]=fn};h.context.SpeechSynthesisUtterance=Utterance;h.context.window.SpeechSynthesisUtterance=Utterance;h.context.window.speechSynthesis=engine;h.run('renderReadingVoices()');return {spoken,engine,events,setVoices:rows=>voices=rows};}
test('personal photo recovery keeps the private photo and ignores a failure from the replaced built-in scene',async()=>{const h=harness();await h.ready();const images=[];h.context.Image=class{constructor(){images.push(this);}};h.run("studioRecords=[{id:'quote-photo',kind:'background',updated:123,payload:{image:'data:image/jpeg;base64,YQ=='}}];state.background='auto';updateQuoteBackground()");const photo=images.at(-1);assert.equal(photo.src,'data:image/jpeg;base64,YQ==');images[0].onerror();await Promise.resolve();await Promise.resolve();assert.equal(h.get('photo-recovery').hidden,true);photo.onerror();await Promise.resolve();await Promise.resolve();assert.equal(h.get('photo-recovery').hidden,false);h.get('photo-retry').handlers.click();assert.equal(images.at(-1).src,'data:image/jpeg;base64,YQ==');images.at(-1).onload();await Promise.resolve();assert.equal(h.get('photo-recovery').hidden,true);assert.equal(h.run('studioRecords[0].payload.image'),'data:image/jpeg;base64,YQ==');h.get('photo-use-plain').handlers.click();assert.equal(h.run('state.background'),'none');assert.equal(h.run('studioRecords.length'),1);});
test('failed card speech offers a direct automatic retry without changing quote history or running stale completion',async()=>{const h=harness();await h.ready();const s=installSpeech(h);const before=h.run('JSON.stringify(state.seen)'),id=h.run('current.id');h.run("studioPrefs.speech={voice:'voice-uk',rate:1.3,pitch:.8};globalThis.completed=0;speakWords(current.text,()=>completed++,'en');speechDidNotStart(speechGeneration)");const first=s.spoken[0];assert.equal(h.get('quote-speech-recovery').hidden,false);h.get('speech-retry').onclick();assert.equal(s.spoken.length,2);assert.equal(s.spoken[1].voice,undefined);assert.equal(s.spoken[1].rate,.9);assert.equal(h.get('quote-speech-recovery').hidden,true);first.onend();assert.equal(h.run('completed'),0);assert.equal(h.run('current.id'),id);assert.equal(h.run('JSON.stringify(state.seen)'),before);s.spoken[1].onerror({error:'not-allowed'});assert.equal(h.get('quote-speech-recovery').hidden,false);h.get('speech-help').onclick();assert.equal(h.run('voiceDialog.open'),true);});
test('speech API failures preserve recovery controls and allow a later user retry',async()=>{const h=harness();await h.ready();const s=installSpeech(h);s.engine.getVoices=()=>{throw Error('Voice list unavailable');};assert.doesNotThrow(()=>h.run('renderReadingVoices();readCurrent()'));s.engine.cancel=()=>{throw Error('Speech engine unavailable');};assert.doesNotThrow(()=>h.run('stopSpeech()'));s.engine.speak=()=>{throw Error('Cannot speak');};h.run('readCurrent()');assert.equal(h.run('activeUtterance'),null);assert.equal(h.get('quote-speech-recovery').hidden,false);assert.equal(h.get('speak-quote').attrs['aria-pressed'],'false');h.context.SpeechSynthesisUtterance=class{constructor(){throw Error('Cannot prepare speech');}};assert.doesNotThrow(()=>h.run('readCurrent()'));assert.match(h.get('voice-status').textContent,/could not prepare/);});
test('speech start events never confirm that a person heard sound',async()=>{const h=harness();await h.ready();const s=installSpeech(h);h.get('sound-check-heard').onclick();assert.ok(!h.get('sound-check-status').textContent.includes('You confirmed'));h.get('sound-check-start').onclick();s.spoken[0].onstart();s.spoken[0].onend();assert.ok(!h.get('sound-check-status').textContent.includes('You confirmed'));h.get('sound-check-heard').onclick();assert.match(h.get('sound-check-status').textContent,/You confirmed hearing/);assert.equal(h.get('sound-check-heard').disabled,true);});
test('reporting a silent sound check stops audio and gives speaker and Safari steps',async()=>{const h=harness();await h.ready();const s=installSpeech(h);h.get('sound-check-start').onclick();h.get('sound-check-silent').onclick();assert.equal(h.run('activeUtterance'),null);assert.match(h.get('sound-check-status').textContent,/Sound is not confirmed/);assert.match(h.get('sound-check-status').textContent,/Bluetooth/);assert.equal(h.get('quote-speech-recovery').hidden,false);s.spoken[0].onend();assert.match(h.get('sound-check-status').textContent,/Sound is not confirmed/);});
test('card reading action reads the current quote and toggles to stop without changing reading history',async()=>{const h=harness();await h.ready();const speech=installSpeech(h);const text=h.run('current.text'),seen=h.run('JSON.stringify(state.seen)');h.get('speak-quote').onclick();assert.equal(speech.spoken[0].text,text);assert.match(h.get('speak-quote').textContent,/Stop reading/);assert.equal(h.get('speak-quote').attrs['aria-pressed'],'true');h.get('speak-quote').onclick();assert.equal(h.run('activeUtterance'),null);assert.match(h.get('speak-quote').textContent,/Read aloud/);assert.equal(h.get('speak-quote').attrs['aria-pressed'],'false');assert.equal(h.run('JSON.stringify(state.seen)'),seen);});
test('reading resumes a paused engine and retains the utterance until completion',async()=>{const h=harness();await h.ready();const s=installSpeech(h);let resumes=0,cancels=0;s.engine.paused=true;s.engine.resume=()=>{resumes++;s.engine.paused=false;};const cancel=s.engine.cancel;s.engine.cancel=()=>{cancels++;cancel();};h.run('readCurrent()');assert.equal(resumes,1);assert.equal(cancels,0);assert.equal(h.run('activeUtterance'),s.spoken[0]);assert.equal(s.spoken[0].volume,1);s.spoken[0].onstart();s.spoken[0].onend();assert.equal(h.run('activeUtterance'),null);assert.equal(h.get('quote-speech-stop').disabled,true);});
