const MG=require('../growth-core.js');
test('custom mood colors choose readable text and confidence goals open a relevant journey',()=>{assert.equal(MG.textColor('#000000'),'#ffffff');assert.equal(MG.textColor('#ffffff'),'#000000');assert.equal(MG.textColor('#101010'),'#ffffff');assert.equal(MG.recommendation({goal:'confidence',hour:12}).tool,'journey');});
test('habit periods use Monday weeks across year boundaries and calendar months',()=>{assert.equal(MG.period('2027-01-01','weekly'),'2026-12-28');assert.equal(MG.period('2026-10-20','monthly'),'2026-10');assert.equal(MG.validDay('2026-02-30'),false);assert.equal(MG.validDay('2026-13-01'),false);assert.equal(MG.validDay('2028-02-29'),true);const logs=[{payload:{habit:'a',day:'2026-10-19'}},{payload:{habit:'a',day:'2026-10-20'}},{deleted:true,payload:{habit:'a',day:'2026-10-20'}},{payload:{habit:'b',day:'2026-10-20'}}];assert.equal(MG.habitCount({id:'a',cadence:'weekly'},logs,'2026-10-21'),2);});
test('journal search combines all words and inclusive dates; CSV blocks spreadsheet formulas',()=>{const entries=[{day:'2026-10-19',note:'A quiet walk beside the river'},{day:'2026-10-20',note:'A quiet morning'},{day:'2026-10-21',note:'Walk with a friend'}];assert.equal(MG.search(entries,{query:'QUIET walk'}).length,1);assert.equal(MG.search(entries,{from:'2026-10-20',to:'2026-10-20'}).length,1);const csv=MG.csv([['=1+1','a"b','line\nbreak','@cmd']]);assert.match(csv,/'=1\+1/);assert.match(csv,/a""b/);assert.match(csv,/'@cmd/);});
test('daily meditation has 14 distinct originals; personalized suggestions vary by context',()=>{const titles=new Set();for(let d=1;d<=14;d++)titles.add(MG.dailyMeditation('2026-10-'+String(d).padStart(2,'0')).title);assert.equal(titles.size,14);assert.equal(MG.recommendation({mood:'overwhelmed',hour:12}).kind,'ground');assert.equal(MG.recommendation({hour:23}).tool,'sleep');assert.equal(MG.recommendation({goal:'focus',hour:12}).tool,'focus');assert.equal(MG.recommendation({minutes:1,hour:12}).kind,'body');assert.equal(new Set(MG.stories.map(s=>s.text)).size,4);});
