test('journal recovery preserves encrypted content, locks search, and restores the same record ID',async()=>{const h=harness();await h.ready();await h.run("saveJournal({day:'2026-10-20',note:'A recoverable private thought'})");const id=[...h.records.keys()][0];await h.run('deleteRecord(studioRecords.find(r=>r.kind==="journal"))()');assert.equal(h.records.get(id).deleted,true);h.get('vault-password').value='a-secure-testing-phrase';await h.get('vault-enable').onclick();assert.ok(h.records.get(id).encrypted);assert.ok(!JSON.stringify([...h.records.values()]).includes('recoverable private'));h.get('journal-trash').checked=true;await h.run('renderJournal()');assert.equal(h.get('journal-list').children.length,1);const restore=h.get('journal-list').children[0].children.find(c=>c.textContent==='Restore entry');await restore.onclick();assert.equal(h.records.get(id).deleted,false);assert.equal([...h.records.values()].filter(r=>r.kind==='journal').length,1);h.run('lockJournal()');await assert.rejects(h.run('journalEntries()'),/Unlock/);assert.equal(h.get('journal-list').children.length,0);});
