function loadAudioTools(h){for(const file of ['audio-tools-core.js','audio-tools.js'])vm.runInContext(fs.readFileSync(path.join(root,file),'utf8'),h.context,{filename:file});}
test('editable quote queue repeats and stops without consuming quote history or accepting late callbacks',async()=>{const h=harness();await h.ready();const speech=installSpeech(h);loadAudioTools(h);h.run("state.audio.queue=reminders.slice(0,2).map(q=>({kind:'quote',id:q.id}));state.audio.repeatItem=true");const seen=h.run('JSON.stringify(state.seen)');h.get('audio-queue-play').handlers.click();assert.equal(speech.spoken.length,1);speech.spoken[0].onend();assert.equal(speech.spoken.length,2);assert.equal(speech.spoken[1].text,speech.spoken[0].text);const late=speech.spoken[1].onend;h.get('audio-queue-stop').handlers.click();late();assert.equal(speech.spoken.length,2);assert.equal(h.run('JSON.stringify(state.seen)'),seen);});
