test('word highlighting preserves the quote text, ignores stale events and restores live-region behavior on stop',async()=>{const h=harness();await h.ready();const speech=installSpeech(h);loadAudioTools(h);const make=h.context.document.createElement;h.context.document.createElement=()=>{const n=make(),classes=new Set();n.classes=classes;n.classList.toggle=(key,on)=>{on?classes.add(key):classes.delete(key);};return n;};const parent={attrs:{'aria-live':'polite'},getAttribute(k){return this.attrs[k]||null;},setAttribute(k,v){this.attrs[k]=v;},removeAttribute(k){delete this.attrs[k];}};h.get('quote-text').parentElement=parent;h.run('state.audio.highlight=true;readCurrent()');const utterance=speech.spoken.at(-1),text=h.run('current.text'),index=text.indexOf(' ')+1;utterance.onboundary({charIndex:index});const spans=h.get('quote-text').children.filter(n=>n.classes);assert.equal(spans.filter(n=>n.classes.has('spoken-word')).length,1);assert.equal(h.get('quote-text').children.map(n=>n.textContent).join(''),text);h.run('stopSpeech()');utterance.onboundary({charIndex:index});assert.equal(h.get('quote-text').textContent,text);assert.equal(parent.attrs['aria-live'],'polite');});

