test('extended vault preserves media IDs, seals titles/content/transcripts and clears readable views on lock',async()=>{const h=harness();await h.ready();installMediaVault(h);await h.run("dbWrite([{id:'voice-fixture',kind:'voice',updated:1,payload:{title:'Synthetic private voice',audio:'data:audio/wav;base64,AA==',transcript:'Private test words'}},{id:'vision-fixture',kind:'vision',updated:2,payload:{title:'Synthetic private picture',image:'data:image/png;base64,AA=='}}])");await enableTestMediaVault(h);h.get('media-vault-voice').checked=true;h.get('media-vault-vision').checked=true;await h.get('media-vault-review').onclick();await h.get('media-vault-confirm').onclick();assert.ok(h.records.get('voice-fixture').encrypted);assert.equal(h.records.get('voice-fixture').payload,undefined);assert.ok(h.records.get('vision-fixture').encrypted);assert.ok(!JSON.stringify([...h.records.values()]).includes('Private test words'));assert.equal(h.run("studioReadableRows().find(r=>r.id==='voice-fixture').payload.title"),'Synthetic private voice');const full=await h.run('fullStudioBackup()');h.context.mediaBackup=full;h.run('validateStudioRows(mediaBackup.records)');h.run('lockJournal()');assert.equal(h.run("studioReadableRows().some(r=>r.id==='voice-fixture')"),false);assert.equal(h.run('motiveMediaCache.size'),0);await assert.rejects(h.run("startRecording('voice')"),/Unlock/);await assert.rejects(h.run("dbWrite([{id:'new-voice',kind:'voice',updated:3,payload:{title:'No locked write',audio:'data:audio/wav;base64,AA=='}}])"),/Unlock/);h.get('vault-password').value='synthetic-media-vault-2026';await h.get('vault-open').onclick();assert.equal(h.run("studioReadableRows().find(r=>r.id==='voice-fixture').payload.transcript"),'Private test words');await h.run("dbWrite([{...studioReadableRows().find(r=>r.id==='voice-fixture'),updated:Date.now(),payload:{title:'Changed private title',audio:'data:audio/wav;base64,AA==',transcript:'Updated private transcript'}}])");assert.ok(h.records.get('voice-fixture').encrypted);assert.ok(!JSON.stringify([...h.records.values()]).includes('Updated private transcript'));});
test('locking while private media decrypts cannot repopulate its readable cache',async()=>{const h=harness();await h.ready();installMediaVault(h);await enableTestMediaVault(h);h.get('media-vault-voice').checked=true;await h.get('media-vault-review').onclick();await h.get('media-vault-confirm').onclick();await h.run("dbWrite([{id:'v',kind:'voice',updated:1,payload:{title:'Guarded fixture',audio:'data:audio/wav;base64,AA=='}}])");const pending=h.run('loadMotivePrivateMedia()');h.run('lockJournal()');await pending;assert.equal(h.run('motiveMediaCache.size'),0);assert.equal(h.records.get('v').payload,undefined);});
test('a collection changed after encryption review aborts migration without changing originals',async()=>{const h=harness();await h.ready();installMediaVault(h);await enableTestMediaVault(h);await h.run("dbWrite([{id:'v1',kind:'voice',updated:1,payload:{title:'First fixture',audio:'data:audio/wav;base64,AA=='}}])");h.get('media-vault-voice').checked=true;await h.get('media-vault-review').onclick();await h.run("dbWrite([{id:'v2',kind:'voice',updated:2,payload:{title:'Concurrent fixture',audio:'data:audio/wav;base64,AA=='}}])");await h.get('media-vault-confirm').onclick();assert.equal(h.records.get('v1').encrypted,undefined);assert.equal(h.records.get('v2').encrypted,undefined);assert.match(h.get('media-vault-status').textContent,/collection changed/);});
test('protected collections reject readable backup media and keep protection when merging an older same-vault config',async()=>{const h=harness();await h.ready();installMediaVault(h);await enableTestMediaVault(h);const old=await h.run('fullStudioBackup()');h.get('media-vault-voice').checked=true;await h.get('media-vault-review').onclick();await h.get('media-vault-confirm').onclick();h.context.oldMediaBackup=old;await h.run('importStudioBackup(oldMediaBackup)');assert.equal(h.run("motiveProtectedMedia(currentMediaVaultConfig()).includes('voice')"),true);old.records.push({id:'readable-v',kind:'voice',updated:1,payload:{title:'Readable fixture',audio:'data:audio/wav;base64,AA=='}});h.context.readableMediaBackup=old;await assert.rejects(h.run('importStudioBackup(readableMediaBackup)'),/readable media/);});

test('a failed media encryption batch leaves every original and protection policy unchanged',async()=>{const h=harness();await h.ready();installMediaVault(h);await enableTestMediaVault(h);await h.run("dbWrite([{id:'a',kind:'voice',updated:1,payload:{title:'Fixture a',audio:'data:audio/wav;base64,AA=='}},{id:'b',kind:'voice',updated:2,payload:{title:'Fixture b',audio:'data:audio/wav;base64,AA=='}}])");h.get('media-vault-voice').checked=true;await h.get('media-vault-review').onclick();h.run("var originalTestSeal=seal,sealAttempts=0;seal=async(...args)=>{if(++sealAttempts===2)throw Error('Synthetic encryption failure');return originalTestSeal(...args)}");await h.get('media-vault-confirm').onclick();assert.equal(h.records.get('a').encrypted,undefined);assert.equal(h.records.get('b').encrypted,undefined);assert.equal(h.run("motiveProtectedMedia(currentMediaVaultConfig()).length"),0);assert.match(h.get('media-vault-status').textContent,/Synthetic encryption failure/);});

test('selected-record recovery clears decrypted media caches and restores protected playback views',async()=>{const h=harness();await h.ready();installAccessPrivacy(h);installMediaVault(h);await enableTestMediaVault(h);h.get('media-vault-voice').checked=true;await h.get('media-vault-review').onclick();await h.get('media-vault-confirm').onclick();await h.run("dbWrite([{id:'recover-v',kind:'voice',updated:1,payload:{title:'Recoverable private fixture',audio:'data:audio/wav;base64,AA=='}}])");assert.equal(h.run('motiveMediaCache.size'),1);h.run("motivePrivacyPending=motivePrivacyPlan(studioRecords,['recordings'],'remove')");h.get('privacy-confirm-words').value='APPLY';await h.get('privacy-confirm').onclick();assert.equal(h.records.get('recover-v').deleted,true);assert.equal(h.run('motiveMediaCache.size'),0);h.run("motivePrivacyPending=motivePrivacyPlan(studioRecords,['recordings'],'recover')");h.get('privacy-confirm-words').value='APPLY';await h.get('privacy-confirm').onclick();assert.equal(h.records.get('recover-v').deleted,false);assert.equal(h.run("studioReadableRows().find(r=>r.id==='recover-v').payload.title"),'Recoverable private fixture');});

test('protected recording queues keep IDs, play only after unlock, and cannot restart after lock',async()=>{const h=harness();await h.ready();loadAudioTools(h);installMediaVault(h);const played=[];h.context.Audio=class{constructor(src){this.src=src;this.paused=true;this.volume=1;this.events={};played.push(this);}addEventListener(name,fn){this.events[name]=fn;}play(){this.paused=false;this.events.play?.();return Promise.resolve();}pause(){this.paused=true;this.events.pause?.();}};await enableTestMediaVault(h);h.get('media-vault-voice').checked=true;await h.get('media-vault-review').onclick();await h.get('media-vault-confirm').onclick();await h.run("dbWrite([{id:'queued-private',kind:'voice',updated:1,payload:{title:'Queue private fixture',audio:'data:audio/wav;base64,AA=='}}])");h.run("state.audio.queue=[{kind:'recording',id:'queued-private'}]");const history=h.run('JSON.stringify(state.seen)');h.get('audio-queue-play').handlers.click();assert.equal(played.length,1);const late=played[0].onended;h.run('lockJournal()');assert.equal(played[0].paused,true);late();assert.equal(played.length,1);assert.match(h.run("queueTitle(state.audio.queue[0])"),/Protected recording/);h.get('vault-password').value='synthetic-media-vault-2026';await h.get('vault-open').onclick();h.get('audio-queue-play').handlers.click();assert.equal(played.length,2);assert.equal(played[1].src,'data:audio/wav;base64,AA==');assert.equal(h.run('JSON.stringify(state.seen)'),history);});

