test('library templates preserve private names and words while category choices keep canonical values',()=>{const h=harness();installInterfaceLocale(h);function option(source,explicit){const attrs={};if(explicit!==undefined)attrs.value=explicit;const row={textContent:source,attrs,setAttribute(k,v){attrs[k]=v;},getAttribute(k){return attrs[k]??null;}};Object.defineProperty(row,'value',{get(){return attrs.value??this.textContent;},set(v){attrs.value=v;}});return row;}const categoryOption=option('Focus');h.get('new-category').options=[categoryOption];h.get('new-category').value='Focus';const custom=option('Saved quotes','collection-private-ui');h.get('library-mode').options=[option('All quotes','all'),custom];h.get('library-mode').value='collection-private-ui';h.get('new-quote').value='Saved';h.get('new-author').value='Voice options';h.get('name-input').value='Saved';h.run("state.name='Saved {count}';state.custom=[{id:'personal-library-ui',text:'Saved',author:'Voice options',category:'Focus'}];state.collections=[{id:'collection-private-ui',name:'Your own kind of motivation.',quoteIds:['personal-library-ui']}];collectionMode='collection-private-ui';studioPrefs.language='es';renderLanguage()");assert.equal(categoryOption.value,'Focus');assert.equal(categoryOption.textContent,'Enfoque');assert.equal(h.get('new-category').value,'Focus');assert.equal(custom.textContent,'Saved quotes');assert.equal(h.get('library-mode').value,'collection-private-ui');assert.equal(h.get('collection-title').textContent,'Your own kind of motivation.');assert.equal(h.get('greeting').textContent,'Un poco de inspiración para ti, Saved {count}.');const card=h.get('quote-grid').children[0];assert.equal(card.children[1].textContent,'“Saved”');assert.equal(card.children[2].children[0].textContent,'Voice options');assert.equal(card.children[2].children[1].children[0].attrs['aria-label'],'Guardar cita: Saved');assert.equal(h.get('results-count').textContent,'1 cita');assert.equal(h.get('new-quote').value,'Saved');assert.equal(h.get('new-author').value,'Voice options');assert.equal(h.get('name-input').value,'Saved');h.run("studioPrefs.language='fr';renderLanguage();studioPrefs.language='en';renderLanguage()");assert.equal(categoryOption.value,'Focus');assert.equal(categoryOption.textContent,'Focus');assert.equal(h.run('state.custom[0].text'),'Saved');assert.equal(h.run('state.custom[0].author'),'Voice options');assert.equal(custom.textContent,'Saved quotes');});


test('personal interface language changes preserve mood codes, saved words, drafts and history',()=>{const h=harness();installInterfaceLocale(h);h.run("state.companion.why='Add my why';state.companion.journal[dayKey()]={mood:'overwhelmed',note:'Saved on this device.'}");for(const id of ['personal-why-input','intention-input','reflection-input','collection-name'])h.get(id).value='My unfinished {name} Saved';const before=h.run('JSON.stringify({companion:state.companion,seen:state.seen,ideas:actionIdeas,arrival:arrivalChoices})');h.run("studioPrefs.language='es';renderLanguage()");assert.equal(h.get('personal-why-text').textContent,'Add my why');assert.equal(h.get('arrival-overwhelmed').attrs['aria-pressed'],'true');assert.match(h.get('arrival-feedback').textContent,/demostrar/);assert.equal(h.get('arrival-feedback').attrs.lang,'es');for(const id of ['personal-why-input','intention-input','reflection-input','collection-name'])assert.equal(h.get(id).value,'My unfinished {name} Saved');assert.equal(h.run('JSON.stringify({companion:state.companion,seen:state.seen,ideas:actionIdeas,arrival:arrivalChoices})'),before);h.run("studioPrefs.language='fr';renderLanguage();studioPrefs.language='en';renderLanguage()");assert.equal(h.get('arrival-feedback').textContent,'Nothing to prove here. Take a little space.');assert.equal(h.run('JSON.stringify({companion:state.companion,seen:state.seen,ideas:actionIdeas,arrival:arrivalChoices})'),before);});

