test('scene presentation translates public fields without changing matching, pins, history or design drafts',()=>{const h=harness();installInterfaceLocale(h);installImageStudio(h);h.run("state.pictures.favorites=['mending'];state.pictures.pins[current.id]='mending';state.pictures.presets=[{name:'Choose a saved design',design:{},size:'portrait'}];state.background='mending';updateQuoteBackground();renderMotiveGallery()");h.get('image-preset-name').value='My quiet card {label}';const option={value:'0',textContent:'Choose a saved design',setAttribute(){}};h.get('image-presets').options=[option];h.get('image-presets').value='0';h.get('image-crop-x').value='37';const before=h.run('JSON.stringify({scenes:quoteScenes,pictures:state.pictures,seen:state.seen,scene:displayedQuoteScene})');h.run("studioPrefs.language='fr';renderLanguage();renderMotiveGallery()");assert.equal(h.get('scene-caption').children[0].textContent,'Image fixe');assert.equal(h.get('scene-caption').children[1].textContent,' · Une réparation patiente');assert.ok(h.get('scene-caption').children.every(n=>n.attrs.lang==='fr'));assert.match(h.get('image-pin-status').textContent,/Une réparation patiente/);assert.equal(h.get('image-preset-name').value,'My quiet card {label}');assert.equal(option.textContent,'Choose a saved design');assert.equal(h.get('image-presets').value,'0');assert.equal(h.get('image-crop-x').value,'37');assert.equal(h.run('JSON.stringify({scenes:quoteScenes,pictures:state.pictures,seen:state.seen,scene:displayedQuoteScene})'),before);h.run("studioPrefs.language='es';renderLanguage();studioPrefs.language='en';renderLanguage()");assert.equal(h.get('scene-caption').children[1].textContent,' · A patient repair');assert.equal(h.run('JSON.stringify({scenes:quoteScenes,pictures:state.pictures,seen:state.seen,scene:displayedQuoteScene})'),before);});

