test('translated tour refresh keeps the current step, canonical source and unfinished writing',()=>{const h=harness();installInterfaceLocale(h);h.run(fs.readFileSync(path.join(root,'home-experience.js'),'utf8'));h.run('openMotiveTour()');h.get('tour-next').handlers.click();h.get('tour-next').handlers.click();h.get('intention-input').value='Skip tour {step}';const before=h.run('JSON.stringify({source:motiveTour,seen:state.seen,experience:state.experience})');h.run("studioPrefs.language='es';renderLanguage()");assert.equal(h.get('tour-step').textContent,'Paso 3 de 4');assert.equal(h.get('tour-copy').attrs.lang,'es');assert.equal(h.get('tour-back').disabled,false);assert.equal(h.run('motiveTourStep'),2);assert.equal(h.get('intention-input').value,'Skip tour {step}');h.run("studioPrefs.language='fr';renderLanguage()");assert.equal(h.get('tour-heading').textContent,'Allégez l’accueil');assert.equal(h.get('tour-step').textContent,'Étape 3 sur 4');assert.equal(h.run('JSON.stringify({source:motiveTour,seen:state.seen,experience:state.experience})'),before);h.get('tour-next').handlers.click();assert.equal(h.get('tour-next').textContent,'Terminer');h.get('tour-next').handlers.click();assert.equal(h.run('state.experience.walkthrough'),true);assert.equal(h.get('tour-dialog').open,false);});

