test('quote preference presentation preserves canonical filters, form drafts and private attribution',()=>{const h=harness();installInterfaceLocale(h);installQuotePreferences(h);h.run("state.custom.push({id:'personal-pref-fixture',text:'I can give my own experience a place in this decision.',author:'You {category}',category:'Calm'});state.preferences.revisit=true;state.saved=[reminders[0].id];showQuote(state.custom.at(-1),{revisit:true})");h.get('prefer-muted').value='I, You {pack}';h.get('prefer-tone').value='direct';h.get('prefer-length').value='short';h.get('prefer-pack').value='busy';h.get('quote-context-note').value='Your context note';const before=h.run('JSON.stringify({preferences:state.preferences,seen:state.seen,custom:state.custom,pairs:motivePairs})');h.run("studioPrefs.language='es';renderLanguage()");assert.equal(h.get('quote-origin').textContent,'Autoría que indicaste: You {category}');assert.equal(h.get('quote-reason').textContent,'Uno de tus propios recordatorios.');assert.equal(h.get('favorite-revisit-text').attrs.lang,'es');assert.equal(h.get('prefer-muted').value,'I, You {pack}');assert.equal(h.get('prefer-tone').value,'direct');assert.equal(h.get('prefer-length').value,'short');assert.equal(h.get('prefer-pack').value,'busy');assert.equal(h.get('quote-context-note').value,'Your context note');assert.equal(h.run('JSON.stringify({preferences:state.preferences,seen:state.seen,custom:state.custom,pairs:motivePairs})'),before);h.run("studioPrefs.language='fr';renderLanguage();studioPrefs.language='en';renderLanguage()");assert.equal(h.get('quote-origin').textContent,'Attribution you supplied: You {category}');assert.equal(h.run('state.custom.at(-1).text'),'I can give my own experience a place in this decision.');});

test('paired practice reading uses the displayed language and changed sources fall back to English',()=>{const h=harness();installInterfaceLocale(h);installQuotePreferences(h);const speech=installSpeech(h);h.run("current={...reminders[0],category:'Calm'};studioPrefs.language='es';renderLanguage()");const before=h.run('JSON.stringify(state.seen)'),pairs=h.run('JSON.stringify(motivePairs)');h.get('pair-i').handlers.click();assert.equal(h.run('state.preferences.pair'),'I');assert.equal(h.get('pair-words').attrs.lang,'es');h.get('pair-read').handlers.click();assert.match(speech.spoken.at(-1).lang,/^es(?:-|$)/);assert.equal(speech.spoken.at(-1).text,h.get('pair-words').textContent);h.run("studioPrefs.language='fr';renderLanguage()");h.get('pair-you').handlers.click();h.get('pair-read').handlers.click();assert.match(speech.spoken.at(-1).lang,/^fr(?:-|$)/);assert.equal(h.run('state.preferences.pair'),'You');assert.equal(h.run('JSON.stringify(motivePairs)'),pairs);h.run("motivePairs.Calm.You='A new practice sentence awaiting a reviewed translation.';renderMotivePreferenceLabels()");h.get('pair-read').handlers.click();assert.equal(h.get('pair-words').attrs.lang,'en');assert.match(speech.spoken.at(-1).lang,/^en(?:-|$)/);assert.equal(speech.spoken.at(-1).text,h.get('pair-words').textContent);assert.equal(h.run('JSON.stringify(state.seen)'),before);});

test('context note save status translates while language refresh preserves unfinished note and report values',()=>{const h=harness();installInterfaceLocale(h);installQuotePreferences(h);for(const id of ['settings-dialog','studio-dialog','growth-dialog'])h.get(id).children=[h.context.document.createElement('div')];h.context.location.hash='';for(const name of ['discovery-core.js','discovery.js'])h.run(fs.readFileSync(path.join(root,name),'utf8'));h.get('quote-context-note').value='I {category} <b>Read again</b>';h.get('quote-note-save').handlers.click();h.get('quote-context-note').value='Unfinished You';h.get('quote-report-note').value='Unfinished I';h.get('prefer-muted').value='draft, words';h.get('pair-i').handlers.click();assert.equal(h.get('quote-context-note').value,'Unfinished You');const before=h.run('JSON.stringify(state.preferences)');h.run("studioPrefs.language='es';renderLanguage()");assert.equal(h.get('quote-context-note').value,'Unfinished You');assert.equal(h.get('quote-report-note').value,'Unfinished I');assert.equal(h.get('prefer-muted').value,'draft, words');assert.equal(h.get('quote-note-status').attrs.lang,'es');assert.match(h.get('quote-note-status').textContent,/fuera del diario cifrado/);assert.equal(h.run('JSON.stringify(state.preferences)'),before);assert.equal(h.run('state.preferences.notes[current.id]'),'I {category} <b>Read again</b>');});


