test('localized public tool search preserves canonical results, query state and literal private titles',async()=>{const h=harness();installInterfaceLocale(h);installQuotePreferences(h);installDiscoveryUI(h);h.run("studioPrefs.language='es';renderLanguage()");h.get('motive-search-dialog').open=true;h.get('motive-search-query').value='respiración';h.get('motive-search-kind').value='tool';await h.run('searchMotive()');assert.equal(h.run('motiveSearchResults[0].id'),'calm');assert.equal(h.run('motiveSearchResults[0].title'),'Calming sessions and breathing timers');assert.equal(h.get('motive-search-results').children[0].children[0].textContent,'Sesiones de calma y temporizadores de respiración');const before=h.run('JSON.stringify({results:motiveSearchResults,generation:motiveSearchGeneration,seen:state.seen})');h.run("studioPrefs.language='fr';renderLanguage()");assert.equal(h.get('motive-search-query').value,'respiración');assert.equal(h.get('motive-search-kind').value,'tool');assert.equal(h.get('motive-search-results').children[0].children[0].attrs.lang,'fr');assert.equal(h.get('motive-search-status').textContent,'1 résultat sur cet appareil.');assert.equal(h.run('JSON.stringify({results:motiveSearchResults,generation:motiveSearchGeneration,seen:state.seen})'),before);h.context.literalResult={kind:'collection',id:'private',title:'Calming sessions and breathing timers',detail:'Quote collection'};assert.equal(h.run('presentMotiveSearchResult(literalResult).title.text'),h.context.literalResult.title);assert.equal(h.run('presentMotiveSearchResult(literalResult).title.language'),'en');h.run("literalResult={...motiveToolIndex[0],title:'A changed unreviewed public title'}");assert.equal(h.run('presentMotiveSearchResult(literalResult).title.language'),'en');});

test('translated print output keeps personal words and author values while review files keep canonical source',async()=>{const h=harness();installInterfaceLocale(h);installQuotePreferences(h);installDiscoveryUI(h);const make=h.context.document.createElement,page={document:{body:make('body'),documentElement:make('html'),createElement:make,title:''},printed:0,print(){this.printed++;}};h.context.window.open=()=>page;h.context.captureDownload=(blob,name)=>{h.download={blob,name};};h.run("downloadFile=captureDownload;state.custom.push({id:'personal-print-locale',text:'Search Motive',author:'Saved {category}',category:'Calm'});state.collections=[{id:'collection-print-locale',name:'Private',quoteIds:[reminders[0].id,'personal-print-locale']}];collectionMode='collection-print-locale';studioPrefs.language='es';renderLanguage()");h.get('print-personal').checked=true;const before=h.run('JSON.stringify({seen:state.seen,custom:state.custom})');h.get('quote-pack-print').handlers.click();assert.equal(page.printed,1);assert.equal(page.document.title,'Conjunto de citas de Motive');assert.equal(page.document.body.children[0].textContent,'Palabras para llevar contigo');const personal=page.document.body.children[2];assert.equal(personal.children[0].textContent,'Search Motive');assert.equal(personal.children[0].attrs.lang,'en');assert.equal(personal.children[1].textContent,'Calma · Saved {category}');assert.equal(h.run('JSON.stringify({seen:state.seen,custom:state.custom})'),before);h.get('quote-report-note').value='Saved {author} <b>private fixture</b>';const source=h.run('JSON.stringify({id:current.id,text:current.text,author:current.author})');h.get('quote-report-save').handlers.click();const report=JSON.parse(await h.download.blob.text());assert.equal(JSON.stringify(report.quote),source);assert.equal(report.note,'Saved {author} <b>private fixture</b>');assert.equal(h.get('quote-report-status').attrs.lang,'es');h.run("studioPrefs.language='fr';renderLanguage()");assert.equal(h.get('quote-report-note').value,report.note);assert.equal(h.get('quote-report-status').attrs.lang,'fr');});

