function trackJournalFragments(h){const previous=h.context.document.querySelectorAll;const descendants=node=>[node,...(node.children||[]).flatMap(descendants)];const nodes=()=>[...descendants(h.get('journal-list')),...descendants(h.get('practice-weekly-review')),...descendants(h.get('studio-trends')),...descendants(h.context.document.body)];h.context.document.querySelectorAll=selector=>selector==='[data-motive-journal-word]'?nodes().filter(n=>n.dataset?.motiveJournalWord):selector==='[data-motive-journal-photo]'?nodes().filter(n=>n.dataset?.motiveJournalPhoto):previous(selector);return nodes;}

