test('habit language refresh preserves private titles, plan drafts, weekday choices and disabled actions',async()=>{const h=harness();await h.ready();installPractice(h);installInterfaceLocale(h);trackHabitFragments(h);h.context.rows=[{id:'habit-locale',kind:'habit',updated:1,payload:{title:'Add habit',target:2,cadence:'weekly'}}];await h.run('dbWrite(rows)');h.run("state.practice.habits['habit-locale']={step:'Small version',trigger:'My cue',days:[]};studioPrefs.language='es';$('practice-habit').value='habit-locale';renderHabits();renderLanguage()");const card=h.get('habit-list').children[0];assert.equal(card.children[0].textContent,'Add habit');assert.equal(card.children[1].textContent,'0 de 2 · cada semana');assert.equal(card.children[2].children[0].textContent,'Versión pequeña');assert.equal(card.children[2].children[1].textContent,'Small version');assert.equal(card.children[3].children[1].textContent,'My cue');const mark=card.children[5];assert.equal(mark.disabled,true);h.get('practice-habit-step').value='Your previous steps stay saved.';h.get('practice-habit-trigger').value='A private unfinished cue';h.get('habit-name').value='Archive habit';h.get('habit-cadence').value='monthly';h.get('habit-target').value='3';h.get('practice-day-2').checked=true;const before=h.run('JSON.stringify({practice:state.practice,records:studioRecords,seen:state.seen})');h.run("studioPrefs.language='fr';renderLanguage()");assert.equal(h.get('habit-list').children[0],card);assert.equal(card.children[1].textContent,'0 sur 2 · chaque semaine');assert.equal(card.children[0].textContent,'Add habit');assert.equal(card.children[2].children[1].textContent,'Small version');assert.equal(card.children[3].children[1].textContent,'My cue');assert.equal(mark.disabled,true);assert.equal(h.get('practice-habit-step').value,'Your previous steps stay saved.');assert.equal(h.get('practice-habit-trigger').value,'A private unfinished cue');assert.equal(h.get('practice-habit').value,'habit-locale');assert.equal(h.get('habit-name').value,'Archive habit');assert.equal(h.get('habit-cadence').value,'monthly');assert.equal(h.get('habit-target').value,'3');assert.equal(h.get('practice-day-2').checked,true);assert.equal(h.run('JSON.stringify({practice:state.practice,records:studioRecords,seen:state.seen})'),before);const sunday=h.get('practice-habit-days').children[0].children[2];assert.equal(sunday.textContent,'Dimanche');assert.equal(h.run("motiveHabitProgress(3,{target:5,cadence:'Habit step'}).textContent"),'3 of 5 · Habit step');});

test('translated habit actions keep the same record IDs and preserve mark, undo and archive behavior',async()=>{const h=harness();await h.ready();installPractice(h);installInterfaceLocale(h);trackHabitFragments(h);h.context.rows=[{id:'habit-actions',kind:'habit',updated:1,payload:{title:'Private habit fixture',target:1,cadence:'daily'}}];await h.run('dbWrite(rows)');h.run("studioPrefs.language='es';renderHabits();renderLanguage()");let card=h.get('habit-list').children[0];assert.equal(card.children[2].textContent,'Marcar una vez realizada');await card.children[2].onclick();assert.equal(h.run("growthRows('habit-log').length"),1);card=h.get('habit-list').children[0];assert.equal(card.children[1].textContent,'1 de 1 · cada día');h.run("studioPrefs.language='fr';renderLanguage()");assert.equal(card.children[3].textContent,'Annuler la dernière marque d’aujourd’hui');await card.children[3].onclick();assert.equal(h.run("growthRows('habit-log').length"),0);card=h.get('habit-list').children[0];await card.children[4].onclick();assert.equal(h.records.get('habit-actions').deleted,true);assert.equal(h.records.get('habit-actions').payload.title,'Private habit fixture');assert.equal(h.get('habit-list').children[0].children[0].textContent,'Commencez par une petite habitude');});

test('habit status and celebration language refresh never replays a celebration or changes tracking preferences',async()=>{const h=harness();await h.ready();installPractice(h);installInterfaceLocale(h);trackHabitFragments(h);let animations=0;h.get('practice-celebration').classList.add=()=>animations++;h.run("state.practice.celebrate=true;studioPrefs.language='es';growthMessage('practice-habit-status','Plan saved. Unplanned days have no penalty.');practiceCelebration()");assert.equal(animations,1);assert.equal(h.get('practice-celebration').textContent,'✦ Un pequeño paso cumplido.');const before=h.run('JSON.stringify(state.practice)');h.run("studioPrefs.language='fr';renderLanguage()");assert.equal(animations,1);assert.equal(h.get('practice-celebration').textContent,'✦ Un petit pas accompli.');assert.match(h.get('practice-habit-status').textContent,/Plan enregistré/);assert.equal(h.run('JSON.stringify(state.practice)'),before);h.run("growthMessage('habit-status','Unreviewed personal fixture')");assert.equal(h.get('habit-status').textContent,'Unreviewed personal fixture');assert.equal(h.get('habit-status').attrs.lang,'en');});
function trackTagFragments(h){trackHabitFragments(h);const previous=h.context.document.querySelectorAll,descendants=node=>[node,...(node.children||[]).flatMap(descendants)],nodes=()=>['tag-quote','tag-results','tag-results-status'].flatMap(id=>descendants(h.get(id)));h.context.document.querySelectorAll=selector=>selector==='[data-motive-tag-quote]'?nodes().filter(n=>n.dataset?.motiveTagQuote):selector==='[data-motive-journal-word]'?[...previous(selector),...nodes().filter(n=>n.dataset?.motiveJournalWord)]:previous(selector);return nodes;}

test('tagged quote presentation changes language without translating private tags or rerunning the search',async()=>{const h=harness();await h.ready();installInterfaceLocale(h);trackTagFragments(h);h.run("showQuote(reminders[0],{revisit:true});studioPrefs.language='es'");h.context.tagRow={id:'tag-locale',kind:'quote-tags',updated:1,payload:{quote:h.run('current.id'),tags:['Read this quote']}};await h.run('dbWrite([tagRow])');h.run('renderTags();renderLanguage()');const card=h.get('tag-results').children[0];assert.equal(card.children[0].textContent,'Read this quote');assert.equal(card.children[1].textContent,h.run('presentMotiveQuote(current).text'));assert.equal(card.children[1].attrs.lang,'es');h.get('quote-tags').value='Private unfinished tags';h.get('tag-filter').value='Read';const before=h.run('JSON.stringify({seen:state.seen,records:studioRecords,limit:tagLimit,editor:motiveTagEditorId})');h.run("studioPrefs.language='fr';renderLanguage()");assert.equal(h.get('tag-results').children[0],card);assert.equal(card.children[0].textContent,'Read this quote');assert.equal(card.children[1].attrs.lang,'fr');assert.equal(h.get('quote-tags').value,'Private unfinished tags');assert.equal(h.get('tag-filter').value,'Read');assert.equal(h.get('tag-results-status').children[0].textContent,'Citations étiquetées affichées : 1.');assert.equal(h.run('JSON.stringify({seen:state.seen,records:studioRecords,limit:tagLimit,editor:motiveTagEditorId})'),before);const seen=h.run('JSON.stringify(state.seen)');await card.children[2].onclick();assert.equal(h.run('current.id'),h.context.tagRow.payload.quote);assert.equal(h.run('JSON.stringify(state.seen)'),seen);});

test('tag filtering and clean incoming updates preserve dirty drafts and save tags against the editor quote',async()=>{const h=harness();await h.ready();installInterfaceLocale(h);trackTagFragments(h);h.run('showQuote(reminders[0],{revisit:true});renderTags()');const quote=h.run('current.id');h.get('quote-tags').value='An unfinished private tag';h.get('tag-filter').value='no match';h.get('tag-filter').oninput();assert.equal(h.get('quote-tags').value,'An unfinished private tag');h.context.incoming={id:'tag-incoming',kind:'quote-tags',updated:1,payload:{quote,tags:['Imported fixture']}};await h.run('dbWrite([incoming]);');h.run('renderTags()');assert.equal(h.get('quote-tags').value,'An unfinished private tag');h.get('quote-tags').value='Imported fixture';h.context.incoming.payload.tags=['New incoming fixture'];await h.run('dbWrite([incoming]);');h.run('renderTags()');assert.equal(h.get('quote-tags').value,'New incoming fixture');h.get('quote-tags').value='Saved for the original editor';h.run('current=reminders[1]');await h.get('tags-save').onclick();const saved=h.records.get('tag-incoming');assert.equal(saved.payload.quote,quote);assert.deepEqual(saved.payload.tags,['Saved for the original editor']);assert.equal(h.run('motiveTagEditorId'),h.run('reminders[1].id'));assert.equal(h.get('quote-tags').value,'');});

test('tag cards preserve personal quote words and stale public mappings fall back to English',async()=>{const h=harness();await h.ready();installInterfaceLocale(h);trackTagFragments(h);h.run("state.custom.push({id:'personal-tag-fixture',text:'Read this quote',author:'Private author',category:'Calm'});studioPrefs.language='es'");h.context.rows=[{id:'private-tag',kind:'quote-tags',updated:1,payload:{quote:'personal-tag-fixture',tags:['Tags saved.']}},{id:'orphan-tag',kind:'quote-tags',updated:2,payload:{quote:'deleted-quote-fixture',tags:['Tags saved.']}}];await h.run('dbWrite(rows)');h.run('renderTags();renderLanguage()');const card=h.get('tag-results').children[0];assert.equal(card.children[0].textContent,'Tags saved.');assert.equal(card.children[1].textContent,'Read this quote');assert.equal(card.children[1].attrs.lang,'en');assert.equal(h.get('tag-results-status').children[0].textContent,'Citas etiquetadas mostradas: 1.');h.run("motiveTagQuoteText($('tag-quote'),{...reminders[0],text:'An unreviewed changed reminder'});studioPrefs.language='fr';renderLanguage()");assert.equal(h.get('tag-quote').textContent,'An unreviewed changed reminder');assert.equal(h.get('tag-quote').attrs.lang,'en');assert.equal(h.records.has('orphan-tag'),true);});

test('tag empty states and status replay keep canonical data and unknown messages literal',async()=>{const h=harness();await h.ready();installInterfaceLocale(h);trackTagFragments(h);h.run("studioPrefs.language='es';renderTags();renderLanguage();growthMessage('tag-status','Tags saved.')");const card=h.get('tag-results').children[0];assert.equal(card.children[0].textContent,'No hay citas etiquetadas coincidentes');h.run("studioPrefs.language='fr';renderLanguage()");assert.equal(h.get('tag-results').children[0],card);assert.equal(card.children[0].textContent,'Aucune citation étiquetée correspondante');assert.equal(h.get('tag-status').textContent,'Étiquettes enregistrées.');h.run("growthMessage('tag-status','Unreviewed private fixture')");assert.equal(h.get('tag-status').textContent,'Unreviewed private fixture');assert.equal(h.get('tag-status').attrs.lang,'en');assert.equal(h.records.size,0);});
